-- 全域实际数据库行变更水位，含配置、费用、引用和outbox真实确认；不从账本局部修订冒全域安全截点。
CREATE TABLE gateway_snapshot_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1));
INSERT INTO gateway_snapshot_state(singleton,revision) VALUES(1,1);
CREATE TRIGGER gateway_watermark_attempt_evidence_insert AFTER INSERT ON attempt_evidence BEGIN UPDATE gateway_snapshot_state SET revision=CASE WHEN revision<9223372036854775807 THEN revision+1 ELSE RAISE(ABORT,'gateway_revision_exhausted') END WHERE singleton=1; END;
